export default function build({ THREE, kit, traits, ui, hands }) {
  const root = new THREE.Group();
  root.name = 'Starline - tabletop invaders';

  const M = {
    hull: kit.material('paintedMetal', { color: '#20333e', wear: 0.25 }),
    edge: kit.material('brushedMetal', { color: '#8dacae', metalness: 0.8 }),
    deck: kit.material('rubber', { color: '#10222e' }),
    alien: kit.material('paintedMetal', { color: '#b5d56b', wear: 0.15 }),
    dark: kit.material('metal', { color: '#233039' }),
    cyan: kit.material('light', { color: '#74f5ff', glow: 2 }),
    pink: kit.material('light', { color: '#ff7083', glow: 2 }),
    gold: kit.material('light', { color: '#ffd886', glow: 2 }),
    button: kit.material('glossy', { color: '#65d9bc' }),
    ship: kit.material('ceramic', { color: '#e3ebe4' })
  };
  function mesh(geo, mat, parent, x = 0, y = 0, z = 0) {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    parent.add(m);
    return m;
  }
  function box(w, h, d, mat, parent, x, y, z, r = 0.003) {
    return mesh(kit.roundedBox(w, h, d, r), mat, parent, x, y, z);
  }
  const fixed = new THREE.Group();
  root.add(fixed);
  const shadow = kit.shadow(0.265, 0.35);
  root.add(shadow);
  box(0.44, 0.026, 0.46, M.hull, fixed, 0, 0.017, 0, 0.015);
  box(0.399, 0.007, 0.401, M.deck, fixed, 0, 0.0335, -0.011, 0.012);
  for (const x of [-0.208, 0.208]) {
    box(0.012, 0.019, 0.41, M.edge, fixed, x, 0.035, -0.011);
    box(0.003, 0.003, 0.36, M.cyan, fixed, x, 0.046, -0.01, 0.001);
  }
  box(0.405, 0.017, 0.012, M.edge, fixed, 0, 0.037, -0.218);
  box(0.405, 0.012, 0.036, M.hull, fixed, 0, 0.035, 0.207);

  const grid = [];
  for (let x = -0.18; x <= 0.181; x += 0.03)
    grid.push({ position: [x, 0.0375, -0.015], scale: [1, 1, 1] });
  fixed.add(kit.instances(kit.roundedBox(0.0006, 0.0004, 0.36, 0.0002), M.edge, grid));
  const cross = [];
  for (let z = -0.19; z < 0.18; z += 0.03) cross.push([0, 0.0375, z]);
  fixed.add(kit.instances(kit.roundedBox(0.37, 0.0004, 0.0006, 0.0002), M.edge, cross));
  const bolts = [];
  for (const x of [-0.208, 0.208])
    for (const z of [-0.2, -0.1, 0, 0.1, 0.2]) bolts.push([x, 0.046, z]);
  fixed.add(kit.instances(new THREE.CylinderGeometry(0.0023, 0.0023, 0.0015, 8), M.dark, bolts));
  const danger = [];
  for (let i = 0; i < 13; i++) danger.push([-.18 + i * .03, .039, .122]);
  fixed.add(kit.instances(kit.roundedBox(.014, .001, .003, .001), M.pink, danger));
  kit.merge(fixed);

  const cannon = new THREE.Group();
  cannon.name = 'Hand-controlled interceptor';
  cannon.position.set(0, 0.038, 0.166);
  root.add(cannon);
  const shipOutline = [
    [-.033, -.013], [-.031, .004], [-.017, .009], [-.009, .023],
    [.009, .023], [.017, .009], [.031, .004], [.033, -.013],
    [.014, -.008], [-.014, -.008]
  ];
  const shipGeo = kit.extrude(shipOutline, .012, { bevel: .002 });
  shipGeo.rotateX(-Math.PI / 2);
  mesh(shipGeo, M.ship, cannon, 0, .009, 0);
  mesh(kit.lathe([[0, 0], [.012, 0], [.012, .009], [.008, .016], [0, .018]], 32),
    M.hull, cannon, 0, .012, 0);
  const barrel = mesh(new THREE.CylinderGeometry(.004, .0055, .029, 16),
    M.edge, cannon, 0, .024, -.022);
  barrel.rotation.x = Math.PI / 2;
  const muzzle = box(.012, .008, .005, M.cyan, cannon, 0, .024, -.038);
  for (const x of [-.024, .024]) {
    box(.007, .003, .013, M.cyan, cannon, x, .016, .004);
  }
  const engine = kit.glow('#79efff', .045, { opacity: .45 });
  engine.position.set(0, .014, .018);
  cannon.add(engine);

  // Chunky, upright arcade creatures, with separate eyes and mechanical feet.
  const outline = [
    [-.018, -.009], [-.018, .004], [-.013, .004], [-.013, .012],
    [-.008, .012], [-.008, .017], [-.003, .017], [-.003, .012],
    [.003, .012], [.003, .017], [.008, .017], [.008, .012],
    [.013, .012], [.013, .004], [.018, .004], [.018, -.009],
    [.011, -.009], [.011, -.014], [.005, -.014], [.005, -.008],
    [-.005, -.008], [-.005, -.014], [-.011, -.014], [-.011, -.009]
  ];
  const alienGeo = kit.extrude(outline, .013, { bevel: .001 });
  const eyeGeo = kit.roundedBox(.005, .004, .002, .0008);
  const aliens = [];
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 5; col++) {
      const g = new THREE.Group();
      g.name = 'Invader ' + (row * 5 + col + 1);
      root.add(g);
      mesh(alienGeo, M.alien, g);
      g.add(kit.instances(eyeGeo, row === 0 ? M.pink : M.cyan,
        [[-.007, .003, .0075], [.007, .003, .0075]]));
      box(.01, .003, .002, M.dark, g, 0, -.005, .0075, .0006);
      aliens.push({ g, row, col, alive: true });
    }
  }

  const shots = [], bombs = [];
  const shotGeo = kit.roundedBox(.004, .005, .019, .002);
  const bombGeo = kit.roundedBox(.009, .008, .017, .003);
  for (let i = 0; i < 9; i++) {
    const m = mesh(shotGeo, M.cyan, root);
    m.name = 'Player laser';
    m.visible = false;
    shots.push({ m, active: false });
  }
  for (let i = 0; i < 5; i++) {
    const m = mesh(bombGeo, M.pink, root);
    m.name = 'Enemy bolt';
    m.visible = false;
    bombs.push({ m, active: false });
  }
  const sparks = [];
  const sparkGeo = new THREE.OctahedronGeometry(.0032);
  for (let i = 0; i < 18; i++) {
    const m = mesh(sparkGeo, M.gold, root);
    m.visible = false;
    sparks.push({ m, life: 0, vx: 0, vy: 0, vz: 0 });
  }
  let sparkIndex = 0;
  function burst(x, y, z) {
    for (let i = 0; i < 6; i++) {
      const p = sparks[sparkIndex++ % sparks.length];
      const a = i * Math.PI / 3;
      p.life = .35;
      p.vx = Math.cos(a) * .08;
      p.vy = .06 + (i % 2) * .04;
      p.vz = Math.sin(a) * .08;
      p.m.position.set(x, y, z);
      p.m.visible = true;
    }
  }

  let mode = 'demo', paused = false, score = 0, lives = 3, wave = 1;
  let formationX = 0, descent = 0, direction = 1, remaining = 15;
  let fireClock = 0, bombClock = 1.2, hitFlash = 0, transition = 0;
  const target = new THREE.Vector3();

  function hud(message, tone = 'neutral') {
    panel.set('score', score + ' / 30');
    panel.set('lives', 'Hull ' + lives + ' | Wave ' + wave + ' of 2', lives < 2 ? 'poor' : 'neutral');
    if (message) panel.set('state', message, tone);
  }
  function clearBolts() {
    for (const p of shots) { p.active = false; p.m.visible = false; }
    for (const p of bombs) { p.active = false; p.m.visible = false; }
  }
  function formation() {
    formationX = 0; descent = 0; direction = 1; remaining = 15;
    for (const a of aliens) { a.alive = true; a.g.visible = true; }
  }
  function start() {
    mode = 'play'; paused = false; score = 0; lives = 3; wave = 1;
    hitFlash = 0; transition = 0; fireClock = 0; bombClock = 1.4;
    clearBolts(); formation();
    panel.set('start', 'Restart');
    panel.set('pause', 'Pause');
    hud('Defend the red line!', 'good');
    burst(cannon.position.x, .065, .16);
  }
  function finish(win) {
    mode = 'over'; clearBolts();
    hud(win ? 'Sector clear! All 30 destroyed.' : 'Overrun! Try another sortie.', win ? 'good' : 'bad');
    panel.set('start', 'Play again');
  }
  const panel = kit.panel(ui, {
    width: .36, position: [0, .325, -.215], rotationY: 0,
    title: 'STARLINE',
    items: [
      { text: 'Move your hand to aim; pinch to fire. Stop the invaders.' },
      { stat: '0 / 30', label: 'invaders destroyed', id: 'score' },
      { status: 'Hull 3 | Wave 1 of 2', id: 'lives', tone: 'neutral' },
      { status: 'Demo - press START to defend Earth', id: 'state', tone: 'neutral' },
      { buttons: [
        { label: 'Start', id: 'start', onPress: start },
        { label: 'Pause', id: 'pause', onPress() {
          if (mode !== 'play') return;
          paused = !paused;
          panel.set('pause', paused ? 'Resume' : 'Pause');
          hud(paused ? 'Paused' : 'Defend the red line!');
        } }
      ] }
    ]
  });
  root.add(panel.object3D);
  const startPiece = new THREE.Group();
  startPiece.name = 'START - restart game';
  startPiece.position.set(0, .044, .208);
  root.add(startPiece);
  box(.078, .013, .029, M.button, startPiece, 0, .0065, 0, .006);
  const startLabel = kit.card('START', { width: .064, color: '#74f5ff' });
  startLabel.position.set(0, .016, .005);
  startPiece.add(startLabel);
  traits(startPiece, { onPress: start });

  function shoot() {
    for (const p of shots) {
      if (p.active) continue;
      p.active = true; p.m.visible = true;
      p.m.position.set(cannon.position.x, .064, .126);
      fireClock = .24;
      muzzle.scale.set(1.65, 1.65, 1.65);
      return;
    }
  }
  function enemyFire() {
    const startIndex = Math.floor(Math.random() * aliens.length);
    for (let k = 0; k < aliens.length; k++) {
      const a = aliens[(startIndex + k) % aliens.length];
      if (!a.alive) continue;
      for (const b of bombs) {
        if (b.active) continue;
        b.active = true; b.m.visible = true;
        b.m.position.copy(a.g.position);
        return;
      }
      return;
    }
  }

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, .05);
      startPiece.children[0].scale.y = 1 + .06 * Math.sin(time * 3);
      if (paused) return;
      fireClock -= dt;
      muzzle.scale.lerp(target.set(1, 1, 1), Math.min(1, dt * 16));
      hitFlash = Math.max(0, hitFlash - dt);
      cannon.visible = hitFlash <= 0 || Math.floor(hitFlash * 18) % 2 === 0;
      const hand = hands.right.tracked ? hands.right : hands.left.tracked ? hands.left : null;
      if (mode === 'play') {
        if (hand) {
          target.set(THREE.MathUtils.clamp(hand.tip.x, -.163, .163), .038, .166);
          cannon.position.lerp(target, Math.min(1, dt * 18));
          if ((hand.pinched || hand.pinching) && fireClock <= 0 && transition <= 0) shoot();
        }
      } else if (mode === 'demo') {
        cannon.position.x = Math.sin(time * 1.1) * .135;
        if (fireClock <= 0) shoot();
      }
      for (const p of sparks) {
        if (p.life <= 0) continue;
        p.life -= dt;
        p.m.visible = p.life > 0;
        p.m.position.x += p.vx * dt;
        p.m.position.y = Math.max(.04, p.m.position.y + p.vy * dt);
        p.m.position.z += p.vz * dt;
        p.vy -= .32 * dt;
        p.m.scale.setScalar(Math.max(.05, p.life / .35));
      }
      if (mode === 'over') return;
      if (transition > 0) {
        transition -= dt;
        if (transition <= 0) { formation(); hud('Wave 2 - faster formation!', 'poor'); }
        return;
      }
      const speed = .023 + (15 - remaining) * .002 + (wave - 1) * .012;
      formationX += direction * speed * dt;
      if (Math.abs(formationX) > .039) {
        formationX = Math.sign(formationX) * .039;
        direction *= -1;
        descent += mode === 'demo' ? .008 : .015;
      }
      if (mode === 'demo' && descent > .10) formation();
      for (const a of aliens) {
        if (!a.alive) continue;
        a.g.position.set(formationX + (a.col - 2) * .065,
          .065 + Math.sin(time * 5 + a.col) * .002, -.158 + a.row * .055 + descent);
        a.g.rotation.z = Math.sin(time * 5 + a.col) * .055;
        if (mode === 'play' && a.g.position.z > .112) { finish(false); return; }
      }
      for (const p of shots) {
        if (!p.active) continue;
        const oldZ = p.m.position.z;
        p.m.position.z -= .57 * dt;
        if (p.m.position.z < -.215) { p.active = false; p.m.visible = false; continue; }
        for (const a of aliens) {
          if (!a.alive || Math.abs(p.m.position.x - a.g.position.x) > .023) continue;
          if (a.g.position.z < p.m.position.z - .013 || a.g.position.z > oldZ + .013) continue;
          p.active = false; p.m.visible = false;
          burst(a.g.position.x, .065, a.g.position.z);
          if (mode === 'play') {
            a.alive = false; a.g.visible = false; remaining--; score++;
            hud(remaining ? 'Direct hit!' : 'Formation cleared!', 'good');
            if (remaining === 0) {
              if (wave === 2) { finish(true); return; }
              wave = 2; transition = 1.1; clearBolts();
              hud('Wave 2 incoming!', 'good');
            }
          }
          break;
        }
      }
      if (mode !== 'play' || transition > 0) return;
      bombClock -= dt;
      if (bombClock <= 0) {
        enemyFire();
        bombClock = Math.max(.55, 1.55 - score * .025);
      }
      for (const b of bombs) {
        if (!b.active) continue;
        b.m.position.z += (.105 + wave * .018) * dt;
        if (Math.abs(b.m.position.z - .166) < .023 &&
            Math.abs(b.m.position.x - cannon.position.x) < .034 && hitFlash <= 0) {
          b.active = false; b.m.visible = false;
          burst(cannon.position.x, .065, .166);
          lives--; hitFlash = 1.2;
          hud('Hull hit! Keep moving.', 'bad');
          if (lives <= 0) { cannon.visible = true; finish(false); return; }
        }
        if (b.m.position.z > .195) { b.active = false; b.m.visible = false; }
      }
    }
  };
}
